"""Candy — two sweeps, left to right and right to left.

The first pass satisfies every "higher than my left neighbour" constraint, the
second the mirrored one; taking the maximum satisfies both at once.

Time: O(n)   Space: O(n)
"""
from typing import List


class Solution:
    def candy(self, ratings: List[int]) -> int:
        n = len(ratings)
        candies = [1] * n
        for i in range(1, n):
            if ratings[i] > ratings[i - 1]:
                candies[i] = candies[i - 1] + 1
        for i in range(n - 2, -1, -1):
            if ratings[i] > ratings[i + 1]:
                candies[i] = max(candies[i], candies[i + 1] + 1)
        return sum(candies)
